  if (!A) return { belakang: '', depan: '', kotak: null };
  const { x, yP, i0, END, PADL, PADR, PADT, W, Hp, bw, vTop, sTop, f } = G;
  const kanan = W - PADR;
  let belakang = '', depan = '';

  const teksBerlatar = (kls, xx, yy, txt, anchor) => {
    const w = txt.length * 4.45 + 6;
    const x0 = anchor === 'end' ? xx - w : xx - 2;
    return '<rect class="an-bg" x="' + f(x0) + '" y="' + f(yy - 8) + '" width="' + f(w) + '" height="10.5" rx="2"/>'
      + '<text class="' + kls + '"' + (anchor === 'end' ? ' text-anchor="end"' : '') + ' x="' + f(xx) + '" y="' + f(yy) + '">' + esc(txt) + '</text>';
  };

  // ── latar negara ────────────────────────────────────────────────────────────
  for (const sg of (A.negaraSeg || [])) {
    if (sg.b < i0 || sg.a >= END) continue;
    const xa = PADL + (Math.max(sg.a, i0) - i0) * bw;
    const xb = PADL + (Math.min(sg.b, END - 1) - i0 + 1) * bw;
    if (!(xb > xa)) continue;
    belakang += '<rect class="ng ng-' + sg.kode + '" x="' + f(xa) + '" y="' + PADT + '" width="' + f(xb - xa) + '" height="' + Hp + '">'
      + '<title>' + esc(sg.label) + ' · ' + (sg.b - sg.a + 1) + ' bar</title></rect>';
    if (xb - xa >= sg.label.length * 5.4 + 12 && W >= 620) {
      depan += '<text class="ng-t ng-t-' + sg.kode + '" x="' + f(xa + 5) + '" y="' + f(PADT + Hp - 5) + '">' + esc(sg.label) + '</text>';
    }
  }

  // ── pita zona ───────────────────────────────────────────────────────────────
