  if (!o.length) return '<div class="sq-cload">belum ada data kepemilikan KSEI untuk nama ini</div>';
  const n = o.length, iw = (W - PADL - PADR) / n, bw = Math.max(6, Math.min(46, iw * 0.62));
  const y = v => PADT + (H - PADT - PADB) * (1 - v / 100);
