  if (b.vonis && b.vonis !== 'BELUM ADA BACAAN') h += `<div class="sq-vonis${b.tone === 'bad' ? ' bad' : b.tone === 'warn' ? ' warn' : ''}"><b>${esc(b.vonis)}.</b> ${esc(b.alasan.join('; '))}.</div>`;
  // grafik
